define(['jquery', 'uiComponent', 'ammenu_helpers'], function($, Component, helpers) {
    'use strict';
    return Component.extend({
        defaults: {
            template: 'Amasty_MegaMenuPremium/submenu/mobile/wrapper',
            imports: {
                color_settings: 'index = ammenu_wrapper:color_settings',
                mobile_class: 'index = ammenu_wrapper:mobile_class'
            },
            links: {
                'actionAnimation': 'index = ammenu_drill_wrapper:actionAnimation'
            }
        },
        initObservable: function() {
            this._super().observe({
                actionAnimation: ''
            });
            return this;
        },
        isContentVisible: function(state) {
            return this.isTypeDrill() ? true : state;
        },
        isTypeDrill: function() {
            return this.mobile_class === 'drill';
        },
        addCustomClass: function() {
            setTimeout(() => {
                jQuery(document).find(".ammenuprem-mobile-content .menuToggle").each(function() {
                    jQuery(this).click(function() {
                        var self = $(this);
                        jQuery(document).find(".ammenuprem-mobile-content  .menuToggle").each(function() {
                            if (!self.next().hasClass("active_class")) {
                                jQuery(this).next().removeClass("active_class");
                                jQuery(this).removeClass("active_item");
                            }
                        });
                        if (jQuery(this).next().hasClass("active_class")) {
                            jQuery(this).next().removeClass("active_class");
                            jQuery(this).removeClass("active_item");
                        } else {
                            jQuery(this).next().addClass("active_class");
                            jQuery(this).addClass("active_item");
                        }
                    })
                })
            }, 1000);
        },
        initContent: function(node, item) {
            helpers.updateFormKey(node);
            helpers.sliderResizeSubscribe(node, item.isActive);
            $(node).trigger('contentUpdated');
            this.addCustomClass();
        }
    });
});